"""Render audited numbers into the requested documentation; no model fitting."""
import json
from pathlib import Path

ROOT=Path(__file__).resolve().parents[1]
FOLDER=ROOT/'eval'/'berka_accounts'
START='<!-- BERKA_ACCOUNT_FEASIBILITY_START -->'
END='<!-- BERKA_ACCOUNT_FEASIBILITY_END -->'


def number(value,digits=0):return f'{value:,.{digits}f}'
def table(headers,rows):
    return '\n'.join(['| '+' | '.join(headers)+' |','|'+'|'.join(['---']*len(headers))+'|',*['| '+' | '.join(str(x) for x in row)+' |' for row in rows]])


def render():
    if (ROOT/'app'/'data'/'low_balance_protocol_v1.json').exists():
        raise SystemExit('Historical proposal renderer disabled after freeze. Use render_low_balance_protocol.py.')
    r=json.loads((FOLDER/'report.json').read_text(encoding='utf-8'))
    history=r['history'];dips=r['balance_dips'];strict=r['candidate_definitions'];relaxed=r['relaxed_observation_sensitivity']
    lines=['## Account eligibility, balance dips and candidate run-out labels — 19 November 2026',
        '**Status: feasibility audit only. No model was fitted, no final spending-category mapping was chosen, and no run-out definition is selected.**',
        'Original ASC hashes were rechecked. The 183,114 bank-generated/unknown-operation rows remain in all balance and cash-flow observations and are excluded from debit/activity/persona counts. This audit does not change the PKR wallet, fill missing balance days, invent transactions or use fictional data.',
        '### 1. Account history and observation cadence',
        f"There are **{r['accounts']:,} accounts**, observed from **{r['dates']['first']} to {r['dates']['last']}**. A calendar-month span includes endpoint months. A **full-span month** is a complete calendar month lying between an account's first and last observed transaction dates. This is a reproducible coverage convention, not proof of complete household budgeting records. Calendar slots with no records mean *no observed transactions*, not verified zero spending.",
        table(['Account-level statistic','Minimum','Median','90th percentile','Maximum'],[
            ['Calendar-month span',*[number(history['calendar_span_months'][k],1) for k in ('min','median','p90','max')]],
            ['Full-span months',*[number(history['full_span_months'][k],1) for k in ('min','median','p90','max')]],
            ['Mean ledger transactions per full month',*[number(history['account_mean_ledger_rows_per_full_month'][k],2) for k in ('min','median','p90','max')]],
            ['Mean eligible debit transactions per full month',*[number(history['account_mean_eligible_debit_rows_per_full_month'][k],2) for k in ('min','median','p90','max')]]]),
        f"There are {history['full_span_account_months']:,} full-span account-months; {history['no_observed_debits_full_months']:,} have no observed eligible debits. The median individual account-month contains {number(history['all_account_month_ledger_rows']['median'])} ledger records and {number(history['all_account_month_debit_rows']['median'])} eligible debit records. Daily LSTM targets would therefore be very sparse. Weekly aggregation or a simpler moving-average/ARIMA baseline deserves comparison; history eligibility alone does not establish that an LSTM is suitable.",
        'The account-level CSV includes first/last observation dates, month spans, mean/median/min/max monthly record counts, counts excluding bank-generated rows, per-purpose eligibility flags and per-account dip counts. See `eval/berka_accounts/account_eligibility.csv`. Monthly observation counts/gaps are in `monthly_observation_coverage.csv`.',
        '### 2. Suggested history thresholds and surviving accounts',
        'These thresholds are **proposals**, not validated model requirements. An active month has at least one observed eligible debit. All debit-volume calculations provisionally include `VYDAJ` and `VYBER` with known operations, including fees and loan repayments: this is total bank outflow, not an approved discretionary-spending target. Category decisions may require this audit to be rerun.',
        '**Forecast:** reserve the last three full months for a source-feasibility backtest. Test history/activity only on the preceding N-month window; do not use those three evaluation months to decide whether the history is active enough. Propose **12 months of history + 3 held-out months**, mean at least four eligible debit records/month and at least 80% active history months.',
        table(['History months','+ evaluation months','History long enough','Also mean >=4 debits/month','Also >=80% active'],[[x['history_months'],3,number(x['history_only_accounts']),number(x['with_mean_4_debits_per_month']),number(x['with_80pct_active_debit_months'])] for x in r['eligibility_proposals']['forecast']]),
        '**Run-out risk:** propose at least **12 completed prior months** at each prediction origin, a historical mean >=4 debits/month, >=80% active prior months, and at least **three assessable target months per account** to regard it as useful for a multi-origin feasibility evaluation. Prediction itself never requires knowing future target-month counts. Each normalization baseline uses the previous three full months with >=3 debit records in each, positive median outflow and an already-observed previous month-end snapshot.',
        'For the conservative assessability proposal, the target month must lie within the observed span, have >=4 distinct transaction dates and no observation gap >10 days, counting both month edges. This is a **retrospective label-availability filter only**, never a predictor or a future-dependent deployment admission rule.',
        table(['Prior history','Accounts with >=1 assessable month','With >=3 months','With >=6 months','Assessable account-months'],[[x['prior_history_months'],number(x['accounts_with_1_scoreable_target']),number(x['accounts_with_3_scoreable_targets']),number(x['accounts_with_6_scoreable_targets']),number(x['scoreable_account_months'])] for x in r['eligibility_proposals']['run_out_risk']]),
        '**Personas:** propose a fixed **six-full-month window**, at least **20 eligible debit records in that window** and >=80% active months. Compare only scale-free shares/ratios; do not use raw account ID, money amounts or tenure as personality features.',
        table(['Most recent full months','Minimum debits in that window','History long enough','Also enough debit records','Also >=80% active'],[[x['full_span_months'],x['min_debit_rows'],number(x['history_only_accounts']),number(x['with_min_debit_rows']),number(x['with_80pct_active_debit_months'])] for x in r['eligibility_proposals']['personas']]),
        'Different N-month windows measure different periods, so these activity-filtered sets are not necessarily nested. A longer historical window can retain an account whose recent activity has declined. The tables above describe full-source feasibility; actual training eligibility must be recomputed at the relevant historical cutoff, as in the split table below.',
        '### 3. Negative and near-zero balances: frequency and observed dip spans',
        'Use every post-transaction balance, including bank-generated interest rows. Near zero is provisionally **0 <= balance <= 5% of median eligible-debit outflow in the three prior qualifying months**. Negative balances are reported separately. The baseline is fixed before the target month; accounts/months without adequate prior observations are unassessable for this relative definition.',
        table(['Observed event','Affected accounts / assessable accounts','Low snapshots / assessable snapshots','Affected dates','All snapshots low on date','Mixed-status dates'],[
            ['Negative',f"{dips['negative']['accounts_ever']:,} / {dips['negative']['account_denominator']:,}",f"{dips['negative']['snapshots']:,} / {dips['negative']['snapshot_denominator']:,}",dips['negative']['observed_low_dates'],dips['negative']['all_snapshots_low_dates'],dips['negative']['mixed_status_dates']],
            ['Nonnegative near-zero',f"{dips['near_zero']['accounts_ever']:,} / {dips['near_zero']['account_denominator']:,}",f"{dips['near_zero']['snapshots']:,} / {dips['near_zero']['snapshot_denominator']:,}",dips['near_zero']['observed_low_dates'],dips['near_zero']['all_snapshots_low_dates'],dips['near_zero']['mixed_status_dates']]]),
        f"Thus {100*dips['negative']['accounts_ever']/4500:.2f}% of all accounts ever have a recorded negative balance. {dips['near_zero']['accounts_ever']:,} accounts have an observed nonnegative thin buffer under the relative rule; {dips['affected_account_overlap']['negative_and_near_zero']} accounts exhibit both kinds at some point. No post-transaction balance is exactly zero. An affected account has a median of {number(dips['negative']['snapshots_per_affected_account']['median'])} negative snapshots (maximum {number(dips['negative']['snapshots_per_affected_account']['max'])}); this is not a count of distinct independent distress events.",
        f"**Same-day ordering:** {r['within_day_ordering']['multiple_transaction_dates']:,} of {r['within_day_ordering']['total_account_dates']:,} account-dates have multiple transactions. There is no within-day timestamp establishing transaction order, so this audit never treats highest trans_id/file position as an end-of-day balance. A mixed-status date has both low and non-low snapshots.",
        'An **observed low run** is consecutive low dates in the sequence of available observation dates, ending at the next observed non-low date or an unassessable boundary. Its span is last-low date minus first-low date; one observed date has span zero. Unobserved gaps can hide recoveries and new dips, so the span is **not a measured continuous duration**. Nonnegative near-zero can also end by becoming negative; its next non-near-zero observation is not necessarily recovery.',
        table(['Run diagnostic','Negative','Nonnegative near-zero'],[
            ['Observed low runs',dips['negative']['observed_runs'],dips['near_zero']['observed_runs']],
            ['Median runs per affected account',number(dips['negative']['runs_per_affected_account']['median'],1),number(dips['near_zero']['runs_per_affected_account']['median'],1)],
            ['Single-observed-day runs',dips['negative']['single_observed_day_runs'],dips['near_zero']['single_observed_day_runs']],
            ['Median observed span, days',number(dips['negative']['observed_run_span_days']['median'],1),number(dips['near_zero']['observed_run_span_days']['median'],1)],
            ['90th-percentile observed span, days',number(dips['negative']['observed_run_span_days']['p90'],1),number(dips['near_zero']['observed_run_span_days']['p90'],1)],
            ['Maximum observed span, days',number(dips['negative']['observed_run_span_days']['max']),number(dips['near_zero']['observed_run_span_days']['max'])],
            ['Runs containing a gap >7 days between low dates',dips['negative']['runs_with_low_observation_gap_gt7_days'],dips['near_zero']['runs_with_low_observation_gap_gt7_days']],
            ['Left-censored runs',dips['negative']['left_censored_runs'],dips['near_zero']['left_censored_runs']],
            ['Right-censored runs',dips['negative']['right_censored_runs'],dips['near_zero']['right_censored_runs']]]),
        f"For runs with a subsequent assessable non-low observation, the median time from last low observation to that next observation is {number(dips['negative']['last_low_to_next_nonlow_observation_days']['median'],1)} days for negatives and {number(dips['near_zero']['last_low_to_next_nonlow_observation_days']['median'],1)} for near-zero. This is an observation interval, not an exact recovery time. Full start/end/gap/censor records are in `negative_observed_runs.csv` and `near_zero_observed_runs.csv`.",
        '**Interpretation limit:** a negative account balance can be an authorized overdraft; a cash withdrawal may move money into cash or another account. Berka does not record available cash elsewhere, student allowance/payday, essential bills or a subjective inability to pay. These events can define observed-account liquidity proxies, but do not establish that someone literally ran out of all money.',
        '### 4. Eligible type and payment-symbol meanings — no category mapping chosen',
        table(['Raw type','Eligible count','Meaning / interpretation'],[
            ['PRIJEM',number(r['eligible_codes']['type_counts']['PRIJEM']),'Credit/inflow; not automatically earnings (may include transfers).'],
            ['VYDAJ',number(r['eligible_codes']['type_counts']['VYDAJ']),'Debit/withdrawal, including payments, fees and transfers.'],
            ['VYBER',number(r['eligible_codes']['type_counts']['VYBER']),'Cash-withdrawal debit variant; all observed rows have operation=VYBER and empty k_symbol. Preserve the raw code.']]),
        table(['Eligible k_symbol','Count','Dictionary meaning / decision context'],[
            ['<empty>','481,881','Unspecified: includes both credits and debits; cannot label as discretionary spending.'],
            ['<whitespace>','53,433','Unspecified; all these eligible rows are VYDAJ. Keep raw blank distinctions in the audit.'],
            ['SLUZBY','155,832','Payment for account statement/bank service; fee, not a food/retail label.'],
            ['SIPO','118,065','Household/combined household payment; not evidence of a food purchase.'],
            ['DUCHOD','30,338','Old-age pension; credit, not spending.'],
            ['POJISTNE','18,500','Insurance payment; candidate non-discretionary obligation.'],
            ['UVER','13,580','Loan repayment; candidate debt-service obligation.'],
            ['SANKC. UROK','1,577','Sanction/penalty interest associated with negative balance; bank charge, not retail consumption.'],
            ['UROK','0 eligible','All 183,114 interest-credit rows have missing operation and are excluded by the approved feature policy; retained in balances/cash flow.']]),
        'The eligible cross-tab is supplied so category choices remain yours:',
        table(['type','k_symbol','Rows'],[[x['type'],x['k_symbol_display'],number(x['rows'])] for x in r['eligible_codes']['type_symbol_cross_tab']]),
        'Full type/operation/symbol counts are in `eligible_operation_symbol_counts.csv`. The original dictionary supports the symbol meanings. The maintained Temporian Financial tutorial additionally identifies VYBER as a withdrawal type: https://temporian.readthedocs.io/en/stable/tutorials/loan_outcomes_prediction/ . The original short dictionary lists only PRIJEM/VYDAJ for type, so the extra raw code and its observed operation cross-tab are explicitly retained. LEASING exists in the standing-order table (341 orders), not as an eligible trans k_symbol; do not fabricate matching transaction labels. No spending-category or debt-exclusion mapping has been implemented by this report.',
        '### 5. Three candidate run-out definitions — none selected',
        'The prediction origin is **00:00 on the first calendar day of month M**. All model features and the reference scale must use data strictly before that origin. Outcomes are evaluated on observed dates **before the last calendar day of M**. Let B be the median observed total eligible-debit outflow in M-3, M-2 and M-1, requiring >=3 debit records in each month and an observed previous month-end snapshot. B contains loan/service/other debit payments until you choose a different mapping. Normalized balance = recorded balance / B; no raw-currency feature is produced.',
        '- **A — Overdraft event:** any observed balance <0 before month end. Simple and auditable, but it identifies overdraft rather than proven personal deprivation.\n- **B — Thin buffer:** any observed balance <5% of B before month end, including negatives. Detects a low relative buffer, but brief intraday dips can qualify.\n- **C — Repeated observed low balance:** every recorded balance on each date in a low run is <=10% of B, the observed run spans at least two calendar days, and there is no gap >7 days or intervening non-low observed date. This demands repeated evidence, not proven continuous persistence.',
        f"Candidate rates below are **development-only**: predeclared train-group accounts with target months through 1996 plus validation-group accounts in 1997. Proposed 1998 test-group target labels/rates are withheld. The conservative gate leaves {strict['results'][0]['account_months']:,} assessable account-months in {strict['results'][0]['accounts']:,} accounts, excluding {strict['excluded_for_outcome_observation']:,} of {strict['cohort_before_outcome_gate']:,} otherwise history-ready development months for sparse outcome observation.",
        table(['Candidate','Positive months / conservative denominator','Positive-month rate','Independent accounts ever positive'],[[x['candidate'],f"{x['positive_account_months']:,} / {x['account_months']:,}",number(x['positive_month_rate_pct'],3)+'%',f"{x['accounts_ever_positive']} / {x['accounts']}"] for x in strict['results']]),
        f"**Observation sensitivity, not a selected replacement:** requiring only two observed dates in a full-span target month and imposing no gap cap gives {relaxed['results'][0]['account_months']:,} development account-months in {relaxed['results'][0]['accounts']:,} accounts. Unobserved dips are more likely to be missed; a negative label is absence of observed evidence, not confirmed financial safety.",
        table(['Same candidate definition','Positive months / relaxed denominator','Positive-month rate','Independent accounts ever positive'],[[x['candidate'],f"{x['positive_account_months']:,} / {x['account_months']:,}",number(x['positive_month_rate_pct'],3)+'%',f"{x['accounts_ever_positive']} / {x['accounts']}"] for x in relaxed['results']]),
        '**Feasibility implication:** the conservative development definitions have only 1–4 positive accounts, and even the relaxed versions have only 5–16. Repeated months from one account are not independent positives. These counts do not currently justify a reliable student run-out classifier or a strong accuracy claim. Do not oversample fake observations, choose a threshold just to inflate positives, or call proxy labels genuine distress ground truth. A deterministic liquidity alert may be more defensible while real student outcomes are collected, but no alternative is selected here.',
        '**Decision required:** choose A, B, C or none, and decide the observation-coverage policy before freezing a target. `selected_definition` remains null in both JSON reports. Exploratory CSV columns are explicitly named candidates and NOT_SELECTED; no final target file or fitted risk model is created.',
        '### 6. Proposed account-and-time split with leakage controls',
        'Assign accounts using SHA-256("spendsense-berka-split-v1:" + account_id), modulo 100: 0–69 train, 70–84 validation, 85–99 test. This seed/rule is fixed without label stratification. There are **3,162 train, 664 validation and 674 test accounts**. Do not reshuffle to obtain more positive labels.',
        table(['Partition','Assigned accounts','Target period','Allowed past at each origin'],[
            ['Training','3,162','Targets ending no later than 1996-12-31','Only earlier records of training accounts.'],
            ['Validation','664','1997 targets','Only those validation accounts’ pre-origin records; all fitted parameters remain training-only.'],
            ['Test','674','1998 targets','Only those test accounts’ pre-origin records; no tuning on test labels.']]),
        f"**Client linkage check:** `disp.asc` was read directly from the same verified ZIP solely for this partition audit (not as model features). Its actual columns are disp_id, client_id, account_id, type. It contains {r['client_linkage_audit']['rows']:,} dispositions, {r['client_linkage_audit']['clients']:,} distinct clients and all 4,500 accounts. No client is attached to multiple accounts in this file, and no client crosses the proposed splits. If another version introduces linked accounts, split connected account/client components together. Demographics and loan outcome fields are not used.",
        'Readiness at the start-of-evaluation historical cutoff is recomputed using only available prefixes, rather than whole-source future histories:',
        table(['Partition','History cutoff','Accounts observed by cutoff','12-month forecast-history ready','6-month/20-debit persona ready'],[[x['partition'],x['history_cutoff'],x['accounts_with_past_observations'],x['forecast_12_history_ready'],x['persona_6_history_ready']] for x in r['split_history_readiness']]),
        'These are history-readiness counts, not a claim that each account already supplies enough independent training/evaluation windows. Later evaluation must construct windows using the agreed target/frequency and report exact surviving windows and accounts.',
        table(['Risk partition','Conservative assessable target months','Accounts','Candidate positives'],[[x['partition'],x['candidate_account_months'],x['accounts_with_candidate_months'],'Withheld' if x['candidate_positives'] is None else ', '.join(k+'='+str(v) for k,v in x['candidate_positives'].items())] for x in strict['split_preview']]),
        'Required controls:\n\n1. Fit scalers, encoders, imputers (if subsequently approved), feature selection, ARIMA settings, LSTM weights, autoencoder thresholds and K-Means centroids on training accounts/time only. Choose K, thresholds and hyperparameters using training/validation, never test. No fitted transform uses full-account future statistics.\n2. All rolling statistics, typical outflow and z-scores use only pre-origin rows. Keep the 183,114 policy-excluded rows out of spending/anomaly/persona feature numerators and denominators; balance/cash-flow/risk outcome observations retain them.\n3. Assign whole sequences to their account partition before forming overlapping windows. Every forecast/risk label horizon must end wholly inside its partition target period. Purge boundary-crossing label windows; do not merely split individual rows or overlapping windows randomly. Historical lookback crossing a calendar boundary is allowed only for the same assigned account and only when the data predates prediction.\n4. Use a fixed six-month pre-cutoff persona window, training-fitted scale-free preprocessing and training-fitted centroids; assign validation/test accounts without refitting. Proposed persona snapshots end in December 1996 for training, December 1997 for validation and December 1998 for test, using only those accounts’ records available by each snapshot. Never use account/client/counterparty IDs, future balances, future sanctions or loan outcomes as predictors.\n5. Distinguish history-based admission from retrospective label ascertainment. Future transaction density cannot be a production feature. Report censoring/excluded months and a coverage sensitivity; do not label sparse/unobserved outcomes as safe.\n6. Freeze label definition, category mapping, cohort rules and model choices before evaluating test targets. Whole-dataset raw balance statistics were examined for this requested feasibility audit, so do not claim the source itself was never inspected. Candidate-rate comparisons are limited to development. Preserve an honest protocol log.\n7. Report metrics with account-level weighting/clustered uncertainty, not falsely independent overlapping windows. Keep household INR data separate and never create fictional additional people or mix raw CZK into the PKR wallet.',
        '### 7. Files and reproduction',
        'All generated files are under `eval/berka_accounts/`: `report.json`, `REPORT.md`, `account_eligibility.csv`, `monthly_observation_coverage.csv`, both observed-run CSVs, type/symbol/operation counts, proposed account assignments and development-only candidate CSVs. The proposed test candidate labels are not exported. These are audit artifacts, not training inputs or claims of trained performance.',
        'From `spendsense`:\n\n```powershell\n../.venv/Scripts/python.exe eval/berka_account_report.py\n../.venv/Scripts/python.exe eval/check_berka_account_report.py\n../.venv/Scripts/python.exe eval/render_berka_account_report.py\n```',
        'Checks passed on original real records: raw source hashes unchanged, 1,056,320 total rows / 873,206 policy-eligible rows, 4,500 accounts, consistent per-account/proposal counts, disjoint account/client assignments, past-only baseline prerequisites, valid censor counts and no selected label/model fits. Independent source reconstruction checked 45 actual candidate account-months and 11 observed negative runs; see `verification.json`. No synthetic test records or pretrained model calls were used.']
    body='\n\n'.join(lines)+'\n'
    (FOLDER/'REPORT.md').write_text(body,encoding='utf-8')
    audit=ROOT/'docs'/'DATA_AUDIT.md';text=audit.read_text(encoding='utf-8')
    block=START+'\n'+body+END
    if START in text:
        beginning=text.index(START);finish=text.index(END,beginning)+len(END);text=text[:beginning]+block+text[finish:]
    else:
        marker='## Historical audit — excluded legacy sources and prior design'
        text=text.replace(marker,block+'\n\n---\n\n'+marker)
    audit.write_text(text,encoding='utf-8')
    print('Rendered account/label audit; selected definition remains unset.')


if __name__=='__main__':render()
